declare(strict_types=1);
spl_autoload_register(static function($class){if(str_starts_with($class,'LandiCy\\'))require __DIR__.'/../landicy-private/src/'.substr($class,8).'.php';});
function e($s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
use LandiCy\Builder;use LandiCy\Pages;use LandiCy\SourceRoots;
$count=0;function verify(bool $ok,string $label):void{global $count;if(!$ok)throw new RuntimeException('FAIL '.$label);echo 'PASS '.$label.PHP_EOL;$count++;}
$example='https://www.youtube-nocookie.com/embed/qIhkkTHTQCU?si=-HwiqGviL9FWQVGs&controls=0&start=20';
foreach([$example,str_replace('&','&amp;',$example),'<iframe onload="evil()" src="'.str_replace('&','&amp;',$example).'"></iframe>','https://www.youtube.com/watch?v=qIhkkTHTQCU&controls=0&start=20','https://youtu.be/qIhkkTHTQCU?controls=0&start=20','https://youtube.com/shorts/qIhkkTHTQCU?controls=0&start=20'] as $url){$safe=Builder::embedUrl($url);verify(str_contains($safe,'/qIhkkTHTQCU?controls=0&start=20'),'YouTube normaliza variante sin perder controles');}
foreach(['javascript:alert(1)','http://youtu.be/qIhkkTHTQCU','https://www.youtube.com.evil.invalid/embed/qIhkkTHTQCU','https://www.youtube.com:444/watch?v=qIhkkTHTQCU','https://u:p@youtu.be/qIhkkTHTQCU','<iframe src="https://youtu.be/qIhkkTHTQCU"></iframe><iframe></iframe>','https://127.0.0.1/','https://youtube.com/feed/yot'] as $url)verify(Builder::embedUrl($url)==='','Embed host/esquema/HTML inválido rechazado');
$blocks=Builder::normalize([['type'=>'embed','url'=>$example,'title'=>'Vídeo']]);verify(isset($blocks[0]['id']),'ID creado para bloque heredado');verify(Builder::normalize($blocks)[0]['id']===$blocks[0]['id'],'ID estable al guardar');
try{Builder::normalize([$blocks[0],$blocks[0]]);throw new Exception('IDs accepted');}catch(InvalidArgumentException){verify(true,'IDs duplicados rechazados');}
$theme=Builder::normalizeTheme(['header_brand'=>'Cabecera global','footer_text'=>'Pie global','header_button_text'=>'Botón global','header_button_url'=>'https://example.invalid','header_visibility'=>'desktop','footer_padding'=>50,'social_links'=>[['kind'=>'link','label'=>'Red social','url'=>'https://example.invalid']]]);
$pages=[['id'=>1,'slug'=>'index','title'=>'Inicio'],['id'=>2,'slug'=>'contacto','title'=>'Contacto']];$site=['id'=>1,'name'=>'Prueba','theme_json'=>json_encode($theme)];
foreach([false,true] as $preview){$html=Builder::html($site,$pages[0],$blocks,$preview,$pages);verify(str_contains($html,'<iframe title="Vídeo"'),'Iframe real editor/preview/export');verify(str_contains($html,'allowfullscreen')&&str_contains($html,'start=20'),'Iframe atributos y parámetros');verify(str_contains($html,'Botón global')&&str_contains($html,'Red social'),'Diseño compartido renderizado');verify(str_contains($html,'contacto'),'Página existente conservada en navegación');}
$theme['pages']=['2'=>['status'=>'trash','order'=>2]];verify(count(Pages::listing($pages,$theme))===1,'Papelera excluida sin borrar página');verify(count(Pages::listing($pages,$theme,true))===2,'Papelera recuperable');$theme['pages']['2']['status']='active';verify(count(Pages::listing($pages,$theme))===2,'Restauración conserva ID y slug');$theme['pages']['2']['status']='hidden';verify(count(Pages::listing($pages,$theme))===2&&count(Pages::listing($pages,$theme,false,true))===1,'Oculta exporta pero no aparece en menú');
$theme['pages']['2']['status']='active';$theme['pages']['2']['layout']=Builder::normalizeLayout(['header_brand'=>'Excepción']);$site['theme_json']=json_encode($theme);verify(str_contains(Builder::html($site,$pages[1],[],true,$pages),'Excepción'),'Excepción por página');verify(isset(Builder::normalizeTheme($theme)['pages'][2]),'Normalización conserva catálogo');
$layout=Builder::normalize([['type'=>'text_box','body'=>'Texto','row'=>'fila','columns'=>2,'widths'=>'2 1','gap'=>20,'border_width'=>2,'radius'=>10]]);$html=Builder::html($site,$pages[0],$layout,true,$pages);verify(str_contains($html,'minmax(0,2fr) minmax(0,1fr)')&&str_contains($html,'border:2px'),'Diseño columnas proporcional y borde');
foreach(['heading','button','form'] as $type){$normalized=Builder::normalize([['type'=>$type]]);verify($normalized[0]['type']===$type,'Bloque nativo '.$type);}
$tmp=sys_get_temp_dir().'/landicy-v050-'.bin2hex(random_bytes(6));mkdir($tmp,0700);mkdir($tmp.'/source',0700);file_put_contents($tmp.'/source/index.html','<p>Origen intacto</p>');$cfg=['scan_root'=>$tmp.'/source'];
mkdir($tmp.'/source/css',0700);file_put_contents($tmp.'/source/css/site.css','body{color:red}');mkdir($tmp.'/source/landicy-admin',0700);file_put_contents($tmp.'/source/landicy-admin/hidden.html','PRIVATE SYNTHETIC');verify(count(LandiCy\Scanner::scanDirectory($tmp.'/source',''))===2,'Escáner recorre CSS anidado y excluye administración');
[$root,$relative]=SourceRoots::resolve($cfg,'default',$tmp.'/source');verify($relative===''&&$root===realpath($tmp.'/source'),'Ruta absoluta solo dentro de raíz autorizada');
foreach([['default','../'],['unknown',''],['default',$tmp]] as [$key,$relative]){try{SourceRoots::resolve($cfg,$key,$relative);throw new Exception('Root accepted');}catch(InvalidArgumentException){verify(true,'Raíz o traversal rechazado');}}
Pages::saveHistory($tmp,1,json_encode($theme));$history=Pages::history($tmp,1);verify(count($history)===1&&Pages::historical($tmp,1,$history[0])['layout']['header_brand']==='Cabecera global','Historial global recuperable');
verify(hash_file('sha256',$tmp.'/source/index.html')===hash('sha256','<p>Origen intacto</p>'),'Origen intacto tras análisis');
// Cleanup explicitly owned synthetic temporary tree only.
unlink($tmp.'/source/css/site.css');rmdir($tmp.'/source/css');unlink($tmp.'/source/landicy-admin/hidden.html');rmdir($tmp.'/source/landicy-admin');unlink($tmp.'/source/index.html');rmdir($tmp.'/source');unlink($tmp.'/layout-history/1/'.$history[0]);rmdir($tmp.'/layout-history/1');rmdir($tmp.'/layout-history');rmdir($tmp);
echo "$count comprobaciones v0.5.0 PASS\n";
